754	    private function anyPlanetHoldsDefence(array $planets): bool
755	    {
756	        foreach ($planets as $planet) {
757	            // A wall already paid for in the yard counts here for the same reason it counts in the
758	            // pass above: the account has left its opening the moment its first wall is bought, so
759	            // the bare siblings are served from that login on rather than one session behind the
760	            // homeworld's queue (measured live 2 Oct 2026: a sibling left at zero defence while the
761	            // account's only wall sat in the yard).
762	            if ($this->defenseNeed->standingUnits($planet) > 0) {
763	                return true;
764	            }
765	        }
766	
767	        return false;
768	    }
769	
770	    /**
771	     * The first wall a planet that holds nothing takes.
772	     *
773	     * The doctrine names the shape, but only among units this planet's yard can actually build: a
774	     * mid-game doctrine's ratio names nothing below a level-two shipyard, while the anchor it could
775	     * build is not in the ratio at all. A young colony's yard sits below every one of them, so the
776	     * composition answered null and the planet stayed naked beside a sibling's wall however often the
777	     * session offered it (measured live 2 Oct 2026: one planet at zero defence beside a sibling
778	     * holding 1,496). The fallback is the host's own cheapest defence unit, so no unit is named here.
779	     */
780	    private function standingDefence(PlayerService $player, PlanetService $planet): ?QueueableUnit
781	    {
782	        $need = $this->defenseNeed->evaluate($player, $planet);
783	        if ($need === null) {
784	            return $this->cheapestQueueableDefence($planet, null);
785	        }
786	
787	        $defense = $this->defenseComposition->plan($player, $planet, $need);
788	        if ($defense !== null && $this->requirementsMet($planet, $defense->unit)) {
789	            // The host refuses an order it cannot pay for whole (QueueUnits: queue_not_created), and a
790	            // planet whose plan repeats that refusal every login stays naked forever, so the order is
791	            // capped by what this planet can actually pay for right now.
792	            $amount = min($defense->amount, $this->affordable($planet, $defense->unit));
793	            if ($amount >= self::FIRST_CARGO_AMOUNT) {
794	                return $this->unit($planet, $defense->unit, 'role:defense:standing:'.$defense->unit->machine_name, $amount, true);
795	            }
796	        }
797	
798	        return $this->cheapestQueueableDefence($planet, $need);
799	    }
800	
801	    /**
802	     * The wall order every bare sibling of the account owes, in planet order.
803	     *
804	     * A player with several naked colonies clicks through all of them before logging off, and the
805	     * invariant reads the account, so one login has to reach them all: a pass that returned a single
806	     * sibling per login needed as many logins as the account has planets, which is longer than its
807	     * own day of sessions, and the cohort read still found planets at zero beside a sibling holding
808	     * a wall (QUAL-003: 3 planets at zero defence while one held 1,312 units). Each order names its
809	     * own planet, so the schedule places them on the planets that stand bare, whatever the login chose.
810	     *
811	     * The order a bare sibling takes is the wall itself when its own yard can build it, and the
812	     * building planner's wall prerequisites stand the yard when it cannot: a login that finds a
813	     * sibling naked beside a wall spends itself on that sibling before the account's habits. Each
814	     * order names the planet it belongs to, so the executor places it on that planet and not on
815	     * whichever planet the login happened to open.
816	     *
817	     * Only an account that already holds a wall somewhere is served: while no wall stands anywhere
818	     * the account is in its opening, where cargo, the colony ship and the probe come first, and the
819	     * standing pass below still reaches the floor once a wall exists. A planet already paid for in
820	     * the yard is no longer bare and is left for the next login.
821	     *
822	     * A sibling whose own yard cannot take the wall yet is left to the building planner: the order
823	     * this pass can place is a defence unit, and a login that can neither place the unit nor stand
824	     * the yard it waits on keeps the sibling naked, so the yard is the planner's own pass and not
825	     * a second facility decision here. A sibling that can take the unit but holds nothing is served
826	     * here whatever its exposure, so the wall reaches every planet the account owns.
827	     *
828	     * A sibling whose yard is already ready but whose balance is below one unit's price is the
829	     * building planner's business too: this pass can only order a wall the host will take whole, so
830	     * the planet is left saving rather than sent a batch that creates no queue row.
831	     *
832	     * @return list<QueueableUnit>
833	     */
834	    // QUAL-003: every bare sibling is asked, so the wallet of one is never the reason another stays zero.
835	    public function standingDefenceOrders(int $playerId, ?PlayerService $player = null): array
836	    {
837	        $profile = AiProfile::query()->where('player_id', $playerId)->where('enabled', true)->first();
838	        if ($profile === null || ! User::query()->whereKey($playerId)->exists()) {
839	            return [];
840	        }
841	
842	        $player ??= $this->playerServiceFactory->make($playerId, true);
843	        $planets = $player->planets->all();
844	        if ($planets === [] || ! $this->anyPlanetHoldsDefence($planets)) {
845	            return [];
846	        }
847	
848	        $orders = [];
849	        foreach ($planets as $planet) {
850	            // The balance is refreshed before the wall is priced: the host refuses an unaffordable batch.
851	            $planet->updateResources(false);
852	            if ($this->defenseNeed->standingUnits($planet) > 0) {
853	                continue;
854	            }
855	
856	            $order = $this->standingDefence($player, $planet);
857	            if ($order !== null) {
858	                $orders[] = $order;
859	            }
860	        }
861	
862	        return $orders;
863	    }
864	
865	    /**
866	     * The defence unit the host prices lowest that this planet's yard can build, in the count the need
867	     * is worth: the same value-to-units arithmetic the composition does, with the host's price of the
868	     * unit the doctrine cannot name here.
869	     */
870	    private function cheapestQueueableDefence(PlanetService $planet, ?DefenseNeed $need, bool $aheadOfEconomy = true): ?QueueableUnit
871	    {
872	        $best = null;
873	        $bestPrice = INF;
874	
875	        foreach (ObjectService::getDefenseObjects() as $unit) {
876	            if (! $unit instanceof UnitObject || ! $this->requirementsMet($planet, $unit)) {
877	                continue;
878	            }
879	
880	            $price = $this->metalEquivalent(ObjectService::getObjectRawPrice($unit->machine_name));
881	            if ($price <= 0.0 || $price >= $bestPrice) {
882	                continue;
883	            }
884	
885	            $best = $unit;
886	            $bestPrice = $price;
887	        }
888	
889	        if ($best === null) {
890	            return null;
891	        }
892	
893	        $amount = min(
894	            $this->affordable($planet, $best),
895	            max(self::FIRST_CARGO_AMOUNT, (int) ceil(($need?->defenceValue ?? 0.0) / $bestPrice))
896	        );
897	
898	        // The host refuses an order it cannot pay for whole, so a planet holding less than one unit's
899	        // price is left to a later login rather than sent a batch that creates no queue row.
900	        if ($amount < self::FIRST_CARGO_AMOUNT) {
901	            return null;
902	        }
903	
904	        return $this->unit($planet, $best, 'role:defense:standing:'.$best->machine_name, $amount, $aheadOfEconomy);
905	    }
906	
907	    /**
908	     * Whether this order would spend a resource the planet is saving for an economy step: a player
909	     * mines while short, and defence comes from what the economy leaves.
910	     */
911	    private function starvesSaving(PlanetService $planet, AiProfile $profile, UnitObject $unit, int $amount): bool
912	    {
913	        $saving = $this->buildingPlanner->savingFor($planet, $profile);
914	        if ($saving === null) {
915	            return false;
916	        }
917	
918	        $price = ObjectService::getObjectPrice($unit->machine_name, $planet);
919	        $held = $planet->getResources();
920	
921	        foreach (['metal', 'crystal', 'deuterium'] as $resource) {
922	            if ($price->{$resource}->get() > 0 && $saving->{$resource}->get() > 0
923	                && $held->{$resource}->get() - $price->{$resource}->get() * $amount < $saving->{$resource}->get()) {
924	                return true;
925	            }
926	        }
927	
928	        return false;
929	    }
930	
931	    private function metalEquivalent(Resources $resources): float
932	    {
933	        return $resources->metal->get()
934	            + self::CRYSTAL_WEIGHT * $resources->crystal->get()
935	            + self::DEUTERIUM_WEIGHT * $resources->deuterium->get();
936	    }
937	}

