334	     * spending the reserve is what the reserve is for.
335	     */
336	    private function canSpendFor(PlanetService $planet, ?SavingsGoal $goal, BuildCandidate $candidate): bool
337	    {
338	        if ($goal === null || $goal->covers($candidate->buildingId)) {
339	            return true;
340	        }
341	
342	        $object = ObjectService::getObjectById($candidate->buildingId);
343	        $hours = $object->type === GameObjectType::Research ? ReserveFloor::RESEARCH_HOURS : ReserveFloor::ECONOMY_HOURS;
344	        $required = $this->withReserve($planet, ObjectService::getObjectPrice($object->machine_name, $planet), $hours);
345	        $spendable = $goal->spendable($planet->getResources());
346	
347	        return $spendable->metal->get() >= $required->metal->get()
348	            && $spendable->crystal->get() >= $required->crystal->get()
349	            && $spendable->deuterium->get() >= $required->deuterium->get();
